window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8bde46261c028249"]={"versions": [{"id": "FIG-8bde46261c028249", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Remote Event Communication Protocols (RecM) im Kontext von AUTOSAR. Dargestellt ist die asynchrone Inter-ECU-Kommunikation zwischen einer PRIMARY-Instanz und einer SECONDARY-Instanz über einen gemeinsamen Fahrzeugbus (BUS) zur Benachrichtigung und Verarbeitung des Modus <code>$04</code> (Process Mode <code>$04</code> Notification).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Systemgrenzen und ein Übertragungsmedium:</p>\n<ul class=\"fig-list\">\n<li><strong>PRIMARY</strong>: Enthält die Software-Entität <code>RecM (Destination)</code> sowie den zugehörigen lokalen Kommunikationsstapel <code>Comm. Stack</code>.</li>\n<li><strong>SECONDARY</strong>: Enthält die Software-Entität <code>RecM (Source)</code> sowie den zugehörigen lokalen Kommunikationsstapel <code>Comm. Stack</code>.</li>\n<li><strong>BUS</strong>: Physischer bzw. logischer Kommunikationsbus zwischen den Kommunikationsstapeln beider Seiten.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Protokollnachrichten:</p>\n<ul class=\"fig-list\">\n<li>Lokale Aufrufe / Trigger an <code>RecM (Destination)</code>: <code>Receive Mode $4 notification</code>, <code>Send Mode $4 notification</code>, <code>Process Mode $4 Return Value</code>.</li>\n<li>Lokaler interner Ablauf an <code>RecM (Source)</code>: <code>Process Mode $4 notification</code>.</li>\n<li>Busnachrichten: Management-Nachricht <code>RECM_MSG_MGMT_MODE4_NOT</code> (auf Source-Seite im Diagramm als <code>RECM_MSG_MGMT_MODE$_NOT</code> typografiert) und Status-/Rückmeldungsnachricht <code>RECM_MSG_STAT_MODE4_RET</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Triggerung auf PRIMARY</strong>: <code>RecM (Destination)</code> erhält den externen/oberen Trigger <code>Receive Mode $4 notification</code> und führt eine interne Aktion <code>Send Mode $4 notification</code> aus.</li>\n<li><strong>Übertragung der Modus-Benachrichtigung</strong>: <code>RecM (Destination)</code> übergibt die Nachricht <code>RECM_MSG_MGMT_MODE4_NOT</code> an den lokalen <code>Comm. Stack</code>. Diese wird über den <code>BUS</code> an den <code>Comm. Stack</code> der SECONDARY übertragen und dort an <code>RecM (Source)</code> zugestellt (beschriftet als <code>RECM_MSG_MGMT_MODE$_NOT</code>).</li>\n<li><strong>Verarbeitung auf SECONDARY</strong>: <code>RecM (Source)</code> startet daraufhin die interne Bearbeitung <code>Process Mode $4 notification</code>.</li>\n<li><strong>Rückmeldung an PRIMARY</strong>: Nach Abschluss der Bearbeitung sendet <code>RecM (Source)</code> die Bestätigungsnachricht <code>RECM_MSG_STAT_MODE4_RET</code> über den lokalen <code>Comm. Stack</code> und den <code>BUS</code> zurück an den <code>Comm. Stack</code> der PRIMARY-Seite, welcher sie an <code>RecM (Destination)</code> weiterleitet.</li>\n<li><strong>Abschluss</strong>: <code>RecM (Destination)</code> schließt den Zyklus mit der internen Verarbeitung des Rückgabewerts (<code>Process Mode $4 Return Value</code>) ab.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlicher Ablauf für das Remote-Event-Kommunikationsprotokoll bei Ausführung von Mode <code>$04</code>:</p>\n<ul class=\"fig-list\">\n<li>Das Sequenzprotokoll erzwingt ein Request/Response- bzw. Notification/Return-Verhalten zwischen Master/Destination (PRIMARY) und Slave/Source (SECONDARY).</li>\n<li>Die Benachrichtigung <code>RECM_MSG_MGMT_MODE4_NOT</code> bedingt zwingend die Antwortnachricht <code>RECM_MSG_STAT_MODE4_RET</code>.</li>\n<li>Implementierer müssen beachten, dass der Eingang der Benachrichtigung auf der SECONDARY-Seite eine asynchrone Bearbeitung (<code>Process Mode $4 notification</code>) anstößt, deren Resultat über das Busprotokoll an die PRIMARY-Einheit zurückzuspiegeln ist.</li>\n<li>Die im Diagramm auftretende Beschriftung <code>RECM_MSG_MGMT_MODE$_NOT</code> auf der SECONDARY-Eingangsseite ist als Notation/Schreibfehler für <code>RECM_MSG_MGMT_MODE4_NOT</code> zu interpretieren.</li>\n</ul>"}, {"id": "FIG-1a20bfa5afbc3f6d", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Remote Event Communication Protocols (RecM) im Kontext von AUTOSAR. Dargestellt ist die asynchrone Inter-ECU-Kommunikation zwischen einer PRIMARY-Instanz und einer SECONDARY-Instanz über einen gemeinsamen Fahrzeugbus (BUS) zur Benachrichtigung und Verarbeitung des Modus <code>$04</code> (Process Mode <code>$04</code> Notification).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Systemgrenzen und ein Übertragungsmedium:</p>\n<ul class=\"fig-list\">\n<li><strong>PRIMARY</strong>: Enthält die Software-Entität <code>RecM (Destination)</code> sowie den zugehörigen lokalen Kommunikationsstapel <code>Comm. Stack</code>.</li>\n<li><strong>SECONDARY</strong>: Enthält die Software-Entität <code>RecM (Source)</code> sowie den zugehörigen lokalen Kommunikationsstapel <code>Comm. Stack</code>.</li>\n<li><strong>BUS</strong>: Physischer bzw. logischer Kommunikationsbus zwischen den Kommunikationsstapeln beider Seiten.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Protokollnachrichten:</p>\n<ul class=\"fig-list\">\n<li>Lokale Aufrufe / Trigger an <code>RecM (Destination)</code>: <code>Receive Mode $4 notification</code>, <code>Send Mode $4 notification</code>, <code>Process Mode $4 Return Value</code>.</li>\n<li>Lokaler interner Ablauf an <code>RecM (Source)</code>: <code>Process Mode $4 notification</code>.</li>\n<li>Busnachrichten: Management-Nachricht <code>RECM_MSG_MGMT_MODE4_NOT</code> (auf Source-Seite im Diagramm als <code>RECM_MSG_MGMT_MODE$_NOT</code> typografiert) und Status-/Rückmeldungsnachricht <code>RECM_MSG_STAT_MODE4_RET</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Triggerung auf PRIMARY</strong>: <code>RecM (Destination)</code> erhält den externen/oberen Trigger <code>Receive Mode $4 notification</code> und führt eine interne Aktion <code>Send Mode $4 notification</code> aus.</li>\n<li><strong>Übertragung der Modus-Benachrichtigung</strong>: <code>RecM (Destination)</code> übergibt die Nachricht <code>RECM_MSG_MGMT_MODE4_NOT</code> an den lokalen <code>Comm. Stack</code>. Diese wird über den <code>BUS</code> an den <code>Comm. Stack</code> der SECONDARY übertragen und dort an <code>RecM (Source)</code> zugestellt (beschriftet als <code>RECM_MSG_MGMT_MODE$_NOT</code>).</li>\n<li><strong>Verarbeitung auf SECONDARY</strong>: <code>RecM (Source)</code> startet daraufhin die interne Bearbeitung <code>Process Mode $4 notification</code>.</li>\n<li><strong>Rückmeldung an PRIMARY</strong>: Nach Abschluss der Bearbeitung sendet <code>RecM (Source)</code> die Bestätigungsnachricht <code>RECM_MSG_STAT_MODE4_RET</code> über den lokalen <code>Comm. Stack</code> und den <code>BUS</code> zurück an den <code>Comm. Stack</code> der PRIMARY-Seite, welcher sie an <code>RecM (Destination)</code> weiterleitet.</li>\n<li><strong>Abschluss</strong>: <code>RecM (Destination)</code> schließt den Zyklus mit der internen Verarbeitung des Rückgabewerts (<code>Process Mode $4 Return Value</code>) ab.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlicher Ablauf für das Remote-Event-Kommunikationsprotokoll bei Ausführung von Mode <code>$04</code>:</p>\n<ul class=\"fig-list\">\n<li>Das Sequenzprotokoll erzwingt ein Request/Response- bzw. Notification/Return-Verhalten zwischen Master/Destination (PRIMARY) und Slave/Source (SECONDARY).</li>\n<li>Die Benachrichtigung <code>RECM_MSG_MGMT_MODE4_NOT</code> bedingt zwingend die Antwortnachricht <code>RECM_MSG_STAT_MODE4_RET</code>.</li>\n<li>Implementierer müssen beachten, dass der Eingang der Benachrichtigung auf der SECONDARY-Seite eine asynchrone Bearbeitung (<code>Process Mode $4 notification</code>) anstößt, deren Resultat über das Busprotokoll an die PRIMARY-Einheit zurückzuspiegeln ist.</li>\n<li>Die im Diagramm auftretende Beschriftung <code>RECM_MSG_MGMT_MODE$_NOT</code> auf der SECONDARY-Eingangsseite ist als Notation/Schreibfehler für <code>RECM_MSG_MGMT_MODE4_NOT</code> zu interpretieren.</li>\n</ul>"}], "trans": [{"from": "FIG-8bde46261c028249", "to": "FIG-1a20bfa5afbc3f6d", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
